import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { Toaster } from "sonner";
import "@/App.css";
import { AuthProvider, useAuth } from "@/context/AuthContext";
import AppLayout from "@/components/AppLayout";
import { Login, Register } from "@/pages/Auth";
import LandingPage from "@/pages/Landing";
import Setup2FA from "@/pages/Setup2FA";
import {
  MerchantDashboard, CreatePayment, Payments, PaymentDetail, Refunds,
  BalanceLedger, Settlement, Withdraw, ApiKeys, Webhooks, Developer, ApiDocs, Account,
} from "@/pages/MerchantPages";
import {
  AdminDashboard, Merchants, MerchantDetail, AdminTransactions, AdminRefunds,
  AdminSettlement, AdminWithdrawals, Fees, AdminLedger, Reports, Fraud, Blacklist, ApiMonitoring,
  WebhookDeliveries, AdminUsers, AuditLogs, AdminSettings,
} from "@/pages/AdminPages";
import { Loader2, Lock } from "lucide-react";
import { MerchantTransactions } from "@/pages/Extra";

function FullLoader() {
  return <div className="min-h-screen flex items-center justify-center text-emerald-600"><Loader2 className="h-8 w-8 animate-spin" /></div>;
}

function Protected({ portal, children }) {
  const { user, loading } = useAuth();
  if (loading) return <FullLoader />;
  if (!user) return <Navigate to="/login" replace />;
  if (user.require_2fa_setup) return <Navigate to="/setup-2fa" replace />;
  if (portal && user.portal !== portal) return <Navigate to={user.portal === "admin" ? "/admin" : "/merchant"} replace />;
  return children;
}

function Setup2FAGate() {
  const { user, loading } = useAuth();
  if (loading) return <FullLoader />;
  if (!user) return <Navigate to="/login" replace />;
  if (!user.require_2fa_setup) return <Navigate to={user.portal === "admin" ? "/admin" : "/merchant"} replace />;
  return <Setup2FA />;
}

function Guard({ perm, children }) {
  const { user } = useAuth();
  if (perm && !user?.permissions?.includes(perm)) {
    return (
      <div className="max-w-md mx-auto text-center py-20" data-testid="access-denied">
        <div className="h-14 w-14 rounded-full bg-red-50 text-red-500 flex items-center justify-center mx-auto mb-4"><Lock className="h-6 w-6" /></div>
        <h2 className="text-xl font-bold font-heading text-slate-900">Akses Ditolak</h2>
        <p className="text-sm text-slate-500 mt-2">Anda tidak memiliki izin untuk mengakses halaman ini.</p>
      </div>
    );
  }
  return children;
}

function Landing() {
  const { user, loading } = useAuth();
  if (loading) return <FullLoader />;
  if (!user) return <Navigate to="/login" replace />;
  return <Navigate to={user.portal === "admin" ? "/admin" : "/merchant"} replace />;
}

export default function App() {
  return (
    <AuthProvider>
      <Toaster position="top-right" richColors />
      <BrowserRouter>
        <Routes>
          <Route path="/" element={<LandingPage />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/setup-2fa" element={<Setup2FAGate />} />

          <Route path="/merchant" element={<Protected portal="merchant"><AppLayout portal="merchant" /></Protected>}>
            <Route index element={<MerchantDashboard />} />
            <Route path="create" element={<CreatePayment />} />
            <Route path="payments" element={<Payments />} />
            <Route path="payments/:id" element={<PaymentDetail />} />
            <Route path="transactions" element={<MerchantTransactions />} />
            <Route path="refunds" element={<Refunds />} />
            <Route path="balance" element={<BalanceLedger />} />
            <Route path="settlement" element={<Settlement />} />
            <Route path="withdraw" element={<Withdraw />} />
            <Route path="api-keys" element={<ApiKeys />} />
            <Route path="webhooks" element={<Webhooks />} />
            <Route path="developer" element={<Developer />} />
            <Route path="docs" element={<ApiDocs />} />
            <Route path="account" element={<Account />} />
          </Route>

          <Route path="/admin" element={<Protected portal="admin"><AppLayout portal="admin" /></Protected>}>
            <Route index element={<AdminDashboard />} />
            <Route path="merchants" element={<Guard perm="merchant.read"><Merchants /></Guard>} />
            <Route path="merchants/:id" element={<Guard perm="merchant.read"><MerchantDetail /></Guard>} />
            <Route path="transactions" element={<Guard perm="transaction.read"><AdminTransactions /></Guard>} />
            <Route path="refunds" element={<Guard perm="refund.read"><AdminRefunds /></Guard>} />
            <Route path="settlement" element={<Guard perm="settlement.read"><AdminSettlement /></Guard>} />
            <Route path="withdrawals" element={<Guard perm="withdrawal.read"><AdminWithdrawals /></Guard>} />
            <Route path="fees" element={<Guard perm="fee.read"><Fees /></Guard>} />
            <Route path="ledger" element={<Guard perm="ledger.read"><AdminLedger /></Guard>} />
            <Route path="reports" element={<Guard perm="report.read"><Reports /></Guard>} />
            <Route path="fraud" element={<Guard perm="fraud.read"><Fraud /></Guard>} />
            <Route path="blacklist" element={<Guard perm="fraud.read"><Blacklist /></Guard>} />
            <Route path="api-monitoring" element={<Guard perm="audit.read"><ApiMonitoring /></Guard>} />
            <Route path="webhooks" element={<Guard perm="webhook.read"><WebhookDeliveries /></Guard>} />
            <Route path="users" element={<Guard perm="user.read"><AdminUsers /></Guard>} />
            <Route path="audit" element={<Guard perm="audit.read"><AuditLogs /></Guard>} />
            <Route path="settings" element={<Guard perm="settings.read"><AdminSettings /></Guard>} />
          </Route>

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </AuthProvider>
  );
}
