import { useFetch, PageHeader, Card, Badge, DataTable, Input, Select } from "@/components/kit";
import { rupiah, fmtDate } from "@/lib/format";
import { useState } from "react";

export function MerchantTransactions() {
  const [q, setQ] = useState("");
  const [status, setStatus] = useState("");
  const { data, loading } = useFetch(`/transactions?search=${q}&status=${status}`, [q, status]);
  return (
    <div>
      <PageHeader title="Transaksi" subtitle="Semua transaksi yang tercatat" />
      <Card>
        <div className="p-4 flex flex-wrap gap-3 border-b border-slate-100">
          <Input placeholder="Cari ID / referensi..." value={q} onChange={(e) => setQ(e.target.value)} className="max-w-xs" data-testid="trx-search" />
          <Select value={status} onChange={(e) => setStatus(e.target.value)} className="max-w-[180px]">
            <option value="">Semua status</option>
            {["PAID", "PENDING", "FAILED", "REFUNDED"].map((s) => <option key={s} value={s}>{s}</option>)}
          </Select>
        </div>
        <DataTable loading={loading} rows={data} columns={[
          { key: "id", label: "TRX ID", render: (r) => <span className="font-mono text-xs">{r.id}</span> },
          { key: "merchant_reference", label: "Referensi", nowrap: true },
          { key: "amount", label: "Nominal", align: "right", render: (r) => rupiah(r.amount) },
          { key: "fee", label: "Fee", align: "right", render: (r) => rupiah(r.fee) },
          { key: "net_amount", label: "Net", align: "right", render: (r) => rupiah(r.net_amount) },
          { key: "payment_method", label: "Metode" },
          { key: "status", label: "Status", render: (r) => <Badge status={r.status} /> },
          { key: "settlement_status", label: "Settlement", render: (r) => <Badge status={r.settlement_status} /> },
          { key: "timestamp", label: "Waktu", nowrap: true, render: (r) => fmtDate(r.timestamp) },
        ]} />
      </Card>
    </div>
  );
}
