import { createContext, useContext, useEffect, useState } from "react";
import api, { apiError } from "@/lib/api";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    const raw = localStorage.getItem("gm_user");
    return raw ? JSON.parse(raw) : null;
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem("gm_token");
    if (!token) { setLoading(false); return; }
    api.get("/auth/me")
      .then(({ data }) => { setUser(data); localStorage.setItem("gm_user", JSON.stringify(data)); })
      .catch(() => { localStorage.removeItem("gm_token"); localStorage.removeItem("gm_user"); setUser(null); })
      .finally(() => setLoading(false));
  }, []);

  const persist = (data) => {
    localStorage.setItem("gm_token", data.access_token);
    localStorage.setItem("gm_refresh", data.refresh_token);
    const u = { ...data.user, require_2fa_setup: !!data.require_2fa_setup };
    localStorage.setItem("gm_user", JSON.stringify(u));
    setUser(u);
  };

  const refreshUser = async () => {
    const { data } = await api.get("/auth/me");
    localStorage.setItem("gm_user", JSON.stringify(data));
    setUser(data);
    return data;
  };

  const login = async (email, password) => {
    try {
      const { data } = await api.post("/auth/login", { email, password });
      if (data.mfa_required) return { ok: false, mfa: true, mfaToken: data.mfa_token };
      persist(data);
      return { ok: true, user: data.user };
    } catch (e) {
      return { ok: false, error: apiError(e.response?.data?.detail) };
    }
  };

  const loginMfa = async (mfaToken, code) => {
    try {
      const { data } = await api.post("/auth/login/mfa", { mfa_token: mfaToken, code });
      persist(data);
      return { ok: true, user: data.user };
    } catch (e) {
      return { ok: false, error: apiError(e.response?.data?.detail) };
    }
  };

  const register = async (payload) => {
    try {
      const { data } = await api.post("/auth/register", payload);
      persist(data);
      return { ok: true, user: data.user };
    } catch (e) {
      return { ok: false, error: apiError(e.response?.data?.detail) };
    }
  };

  const logout = () => {
    localStorage.removeItem("gm_token");
    localStorage.removeItem("gm_refresh");
    localStorage.removeItem("gm_user");
    setUser(null);
    window.location.href = "/login";
  };

  const can = (perm) => user?.permissions?.includes(perm);

  return (
    <AuthContext.Provider value={{ user, loading, login, loginMfa, register, logout, can, refreshUser }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
