import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { QRCodeCanvas } from "qrcode.react";
import { toast } from "sonner";
import api from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { Btn, Field, Input } from "@/components/kit";
import { ShieldCheck, Loader2, Smartphone, LogOut } from "lucide-react";

export default function Setup2FA() {
  const { refreshUser, logout } = useAuth();
  const navigate = useNavigate();
  const [setup, setSetup] = useState(null);
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.post("/auth/2fa/setup")
      .then(({ data }) => setSetup(data))
      .catch((e) => toast.error(e.response?.data?.detail || "Gagal memulai 2FA"))
      .finally(() => setLoading(false));
  }, []);

  const enable = async () => {
    setBusy(true);
    try {
      await api.post("/auth/2fa/enable", { code });
      toast.success("2FA berhasil diaktifkan");
      await refreshUser();
      navigate("/admin", { replace: true });
    } catch (e) {
      toast.error(e.response?.data?.detail || "Kode tidak valid");
    }
    setBusy(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-900 p-6" data-testid="setup-2fa-page">
      <div className="w-full max-w-md bg-white rounded-2xl border border-slate-200 shadow-xl p-8">
        <div className="h-12 w-12 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center mb-5"><ShieldCheck className="h-6 w-6" /></div>
        <h1 className="text-2xl font-bold font-heading text-slate-900">Aktifkan 2FA (Wajib)</h1>
        <p className="text-sm text-slate-500 mt-1">Demi keamanan portal admin, Anda wajib mengaktifkan autentikasi dua faktor sebelum melanjutkan.</p>

        {loading ? (
          <div className="flex items-center justify-center py-16 text-slate-400"><Loader2 className="h-6 w-6 animate-spin" /></div>
        ) : setup ? (
          <div className="mt-6 space-y-5">
            <div className="flex flex-col sm:flex-row gap-5 items-center sm:items-start">
              <div className="p-3 bg-white border border-slate-200 rounded-lg shrink-0">
                <QRCodeCanvas value={setup.otpauth_uri} size={148} data-testid="setup-2fa-qr" />
              </div>
              <div className="text-sm text-slate-600 space-y-2">
                <p className="flex items-center gap-2"><Smartphone className="h-4 w-4 text-slate-400" /> Scan QR dengan Google Authenticator.</p>
                <p className="text-xs text-slate-400">Atau masukkan kunci manual:</p>
                <code className="block text-xs bg-slate-50 border border-slate-200 rounded px-2 py-1 break-all" data-testid="setup-2fa-secret">{setup.secret}</code>
              </div>
            </div>
            <Field label="Masukkan kode 6-digit untuk verifikasi">
              <Input inputMode="numeric" maxLength={6} value={code} onChange={(e) => setCode(e.target.value.replace(/\D/g, ""))} placeholder="123456" autoFocus data-testid="setup-2fa-code" />
            </Field>
            <Btn onClick={enable} disabled={busy || code.length < 6} className="w-full" data-testid="setup-2fa-submit">
              {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : "Verifikasi & Aktifkan"}
            </Btn>
          </div>
        ) : null}

        <button onClick={logout} className="mt-6 w-full flex items-center justify-center gap-2 text-sm text-slate-500 hover:text-slate-700" data-testid="setup-2fa-logout">
          <LogOut className="h-4 w-4" /> Keluar
        </button>
      </div>
    </div>
  );
}
