import { useState } from "react";
import { QRCodeCanvas } from "qrcode.react";
import { toast } from "sonner";
import api from "@/lib/api";
import { useFetch, Card, Btn, Field, Input, Spinner } from "@/components/kit";
import { ShieldCheck, ShieldOff, Loader2, Smartphone } from "lucide-react";

export function TwoFactor() {
  const { data, loading, refetch } = useFetch("/auth/2fa/status");
  const enabled = !!data?.enabled;
  const [setup, setSetup] = useState(null); // {secret, otpauth_uri}
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);

  const startSetup = async () => {
    setBusy(true);
    try {
      const { data } = await api.post("/auth/2fa/setup");
      setSetup(data);
    } catch (e) { toast.error(e.response?.data?.detail || "Gagal memulai 2FA"); }
    setBusy(false);
  };

  const enable = async () => {
    setBusy(true);
    try {
      await api.post("/auth/2fa/enable", { code });
      toast.success("2FA berhasil diaktifkan");
      setSetup(null); setCode(""); refetch();
    } catch (e) { toast.error(e.response?.data?.detail || "Kode tidak valid"); }
    setBusy(false);
  };

  const disable = async () => {
    setBusy(true);
    try {
      await api.post("/auth/2fa/disable", { code });
      toast.success("2FA dinonaktifkan");
      setCode(""); refetch();
    } catch (e) { toast.error(e.response?.data?.detail || "Kode tidak valid"); }
    setBusy(false);
  };

  return (
    <Card className="p-6" data-testid="twofactor-card">
      <div className="flex items-center gap-2 mb-1">
        <ShieldCheck className="h-4 w-4 text-emerald-600" />
        <h3 className="text-sm font-semibold text-slate-700">Autentikasi Dua Faktor (2FA)</h3>
      </div>
      <p className="text-xs text-slate-400 mb-4">Amankan login dengan Google Authenticator / aplikasi TOTP.</p>

      {loading ? (
        <Spinner label="Memuat status 2FA..." />
      ) : enabled ? (
        <div className="space-y-3" data-testid="twofactor-enabled">
          <div className="flex items-center gap-2 text-xs text-emerald-700 bg-emerald-50 border border-emerald-200 rounded-md px-3 py-2">
            <ShieldCheck className="h-4 w-4" /> 2FA aktif pada akun ini.
          </div>
          <Field label="Masukkan kode dari aplikasi untuk menonaktifkan">
            <Input inputMode="numeric" maxLength={6} value={code} onChange={(e) => setCode(e.target.value.replace(/\D/g, ""))} placeholder="123456" data-testid="twofactor-disable-code" />
          </Field>
          <Btn variant="danger" onClick={disable} disabled={busy || code.length < 6} data-testid="twofactor-disable-btn">
            {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <><ShieldOff className="h-4 w-4" /> Nonaktifkan 2FA</>}
          </Btn>
        </div>
      ) : setup ? (
        <div className="space-y-4" data-testid="twofactor-setup">
          <div className="flex flex-col sm:flex-row gap-5 items-center sm:items-start">
            <div className="p-3 bg-white border border-slate-200 rounded-lg shrink-0">
              <QRCodeCanvas value={setup.otpauth_uri} size={148} data-testid="twofactor-qr" />
            </div>
            <div className="text-sm text-slate-600 space-y-2">
              <p className="flex items-center gap-2"><Smartphone className="h-4 w-4 text-slate-400" /> Scan QR dengan Google Authenticator.</p>
              <p className="text-xs text-slate-400">Atau masukkan kunci manual:</p>
              <code className="block text-xs bg-slate-50 border border-slate-200 rounded px-2 py-1 break-all" data-testid="twofactor-secret">{setup.secret}</code>
            </div>
          </div>
          <Field label="Masukkan kode 6-digit untuk verifikasi">
            <Input inputMode="numeric" maxLength={6} value={code} onChange={(e) => setCode(e.target.value.replace(/\D/g, ""))} placeholder="123456" data-testid="twofactor-verify-code" />
          </Field>
          <div className="flex gap-2">
            <Btn onClick={enable} disabled={busy || code.length < 6} data-testid="twofactor-verify-btn">
              {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : "Verifikasi & Aktifkan"}
            </Btn>
            <Btn variant="ghost" onClick={() => { setSetup(null); setCode(""); }}>Batal</Btn>
          </div>
        </div>
      ) : (
        <Btn onClick={startSetup} disabled={busy} data-testid="twofactor-setup-btn">
          {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <><ShieldCheck className="h-4 w-4" /> Aktifkan 2FA</>}
        </Btn>
      )}
    </Card>
  );
}
