import { useState } from "react";
import { NavLink, Outlet, useNavigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { merchantNav, adminNav } from "@/lib/nav";
import { useFetch } from "@/components/kit";
import { Menu, X, LogOut, Bell, ChevronDown, Zap, ShieldCheck } from "lucide-react";

function GomerchBadge() {
  const { data } = useFetch("/gomerch/status");
  const connected = data?.connected;
  return (
    <div className="hidden md:flex items-center gap-2 text-xs px-3 py-1.5 rounded-full border border-slate-200 bg-white" data-testid="gomerch-status">
      <span className={`h-2 w-2 rounded-full ${connected ? "bg-emerald-500 animate-pulse" : "bg-slate-300"}`} />
      <span className="text-slate-600 font-medium">GoMerch {connected ? "Terhubung" : "Terputus"}</span>
      {data?.merchant?.merchant_id && <span className="text-slate-400">· {data.merchant.merchant_id}</span>}
    </div>
  );
}

function NotifBell() {
  const { data, refetch } = useFetch("/notifications");
  const [open, setOpen] = useState(false);
  const items = data || [];
  const unread = items.filter((n) => !n.read).length;
  return (
    <div className="relative">
      <button onClick={() => { setOpen(!open); refetch(); }} className="relative h-9 w-9 rounded-md hover:bg-slate-100 flex items-center justify-center text-slate-600" data-testid="notif-btn">
        <Bell className="h-5 w-5" />
        {unread > 0 && <span className="absolute top-1 right-1 h-4 min-w-4 px-1 rounded-full bg-red-500 text-white text-[10px] flex items-center justify-center">{unread}</span>}
      </button>
      {open && (
        <div className="absolute right-0 mt-2 w-80 bg-white border border-slate-200 rounded-lg shadow-lg z-50 max-h-96 overflow-y-auto">
          <div className="px-4 py-3 border-b border-slate-100 text-sm font-semibold text-slate-800">Notifikasi</div>
          {items.length === 0 ? <div className="px-4 py-6 text-sm text-slate-400 text-center">Tidak ada notifikasi</div> :
            items.slice(0, 15).map((n) => (
              <div key={n.id} className={`px-4 py-3 border-b border-slate-50 ${!n.read ? "bg-emerald-50/40" : ""}`}>
                <p className="text-sm font-medium text-slate-800">{n.title}</p>
                <p className="text-xs text-slate-500 mt-0.5">{n.message}</p>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}

export default function AppLayout({ portal }) {
  const { user, logout } = useAuth();
  const { data: brand } = useFetch("/branding");
  const navigate = useNavigate();
  const [mobileOpen, setMobileOpen] = useState(false);
  const nav = portal === "admin" ? adminNav : merchantNav;
  const can = (p) => user?.permissions?.includes(p);

  const Sidebar = (
    <div className="flex flex-col h-full bg-white border-r border-slate-200 w-64">
      <div className="h-16 flex items-center px-6 border-b border-slate-100">
        <div className="flex items-center gap-2">
          {brand?.logo_url ? (
            <img src={brand.logo_url} alt="logo" className="h-8 w-8 rounded-lg object-cover" />
          ) : (
            <div className="h-8 w-8 rounded-lg bg-emerald-600 flex items-center justify-center">
              <Zap className="h-5 w-5 text-white" />
            </div>
          )}
          <span className="font-heading font-extrabold text-slate-900 text-lg leading-none">{brand?.company_name || "GoMerch Pro"}</span>
        </div>
      </div>
      <nav className="flex-1 overflow-y-auto py-4 px-3">
        {nav.map((section) => {
          const items = section.items.filter((it) => can(it.perm));
          if (items.length === 0) return null;
          return (
            <div key={section.group} className="mb-5">
              <p className="px-3 text-[10px] uppercase tracking-wider font-semibold text-slate-400 mb-2">{section.group}</p>
              {items.map((it) => (
                <NavLink key={it.to} to={it.to} end={it.end} onClick={() => setMobileOpen(false)}
                  data-testid={`nav-${it.to.split("/").pop() || "home"}`}
                  className={({ isActive }) =>
                    `flex items-center gap-3 px-3 py-2 rounded-md text-sm font-medium mb-0.5 transition-colors ${
                      isActive ? "bg-emerald-50 text-emerald-700" : "text-slate-600 hover:bg-slate-100"}`}>
                  <it.icon className="h-[18px] w-[18px] shrink-0" />
                  {it.label}
                </NavLink>
              ))}
            </div>
          );
        })}
      </nav>
      <div className="p-3 border-t border-slate-100">
        <div className="flex items-center gap-3 px-3 py-2 rounded-md">
          <div className="h-9 w-9 rounded-full bg-slate-800 text-white flex items-center justify-center text-sm font-semibold shrink-0">
            {user?.name?.charAt(0)?.toUpperCase()}
          </div>
          <div className="min-w-0 flex-1">
            <p className="text-sm font-medium text-slate-800 truncate">{user?.name}</p>
            <p className="text-xs text-slate-400 flex items-center gap-1"><ShieldCheck className="h-3 w-3" />{user?.role_label}</p>
          </div>
          <button onClick={logout} data-testid="logout-btn" className="text-slate-400 hover:text-red-500 p-1"><LogOut className="h-4 w-4" /></button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex bg-slate-50">
      <aside className="hidden lg:block fixed inset-y-0 left-0 z-30">{Sidebar}</aside>
      {mobileOpen && (
        <div className="lg:hidden fixed inset-0 z-40 flex">
          <div className="fixed inset-0 bg-slate-900/40" onClick={() => setMobileOpen(false)} />
          <div className="relative z-50"><button onClick={() => setMobileOpen(false)} className="absolute -right-10 top-4 text-white"><X className="h-6 w-6" /></button>{Sidebar}</div>
        </div>
      )}
      <div className="flex-1 lg:ml-64 flex flex-col min-w-0">
        <header className="h-16 sticky top-0 z-20 bg-white/80 backdrop-blur-md border-b border-slate-200 flex items-center justify-between px-4 md:px-6">
          <div className="flex items-center gap-3">
            <button className="lg:hidden text-slate-600" onClick={() => setMobileOpen(true)}><Menu className="h-6 w-6" /></button>
            <span className="text-sm font-medium text-slate-500 capitalize">{portal === "admin" ? "Panel Admin" : "Portal Merchant"}</span>
          </div>
          <div className="flex items-center gap-3">
            <GomerchBadge />
            <NotifBell />
          </div>
        </header>
        <main className="flex-1 p-4 md:p-8 animate-fade-in">
          <Outlet />
        </main>
      </div>
    </div>
  );
}
