/* ------------------------------------------------ Admin Dashboard */
export function AdminDashboard() {
  const { data, loading } = useFetch("/dashboard/admin");
  if (loading) return <Spinner />;
  const d = data || {};
  const pie = [
    { name: "Berhasil", value: d.success || 0, color: "#059669" },
    { name: "Pending", value: d.pending || 0, color: "#f59e0b" },
    { name: "Gagal", value: d.failed || 0, color: "#ef4444" },
  ];
  return (
    <div>
      <PageHeader title="Dasbor Platform" subtitle="Ringkasan seluruh aktivitas payment gateway" />
      {d.pending_withdrawals > 0 && (
        <Link to="/admin/withdrawals" className="mb-6 flex items-center gap-3 p-4 rounded-lg bg-amber-50 border border-amber-200 text-sm text-amber-800 hover:bg-amber-100 transition-colors" data-testid="pending-wd-banner">
          <Banknote className="h-4 w-4 shrink-0" />
          <span><b>{d.pending_withdrawals}</b> permintaan penarikan dana menunggu persetujuan.</span>
          <span className="ml-auto font-medium">Tinjau &rarr;</span>
        </Link>
      )}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <StatCard label="Total Merchant" value={d.total_merchants} sub={`${d.active_merchants} aktif · ${d.pending_merchants} pending`} icon={Store} accent="emerald" testid="stat-merchants" />
        <StatCard label="Total Transaksi" value={d.total_transactions} sub={rupiah(d.total_amount)} icon={Receipt} accent="blue" testid="stat-transactions" />
        <StatCard label="Total Fee (Revenue)" value={rupiah(d.total_fee)} icon={TrendingUp} accent="purple" testid="stat-revenue" />
        <StatCard label="Total Settlement" value={rupiah(d.total_settlement)} sub={`${d.refunds} refund`} icon={Landmark} accent="amber" testid="stat-settlement" />
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2 p-6">
          <h3 className="text-base font-semibold text-slate-800 mb-4">Volume Transaksi (7 hari)</h3>
          <ResponsiveContainer width="100%" height={260}>
            <AreaChart data={d.chart || []}>
              <defs><linearGradient id="ga" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#059669" stopOpacity={0.3} /><stop offset="100%" stopColor="#059669" stopOpacity={0} /></linearGradient></defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
              <XAxis dataKey="date" tickFormatter={(v) => v.slice(5)} tick={{ fontSize: 11, fill: "#94a3b8" }} axisLine={false} tickLine={false} />
              <YAxis tickFormatter={compactRupiah} tick={{ fontSize: 11, fill: "#94a3b8" }} axisLine={false} tickLine={false} width={70} />
              <Tooltip formatter={(v) => rupiah(v)} contentStyle={{ borderRadius: 8, border: "1px solid #e2e8f0", fontSize: 12 }} />
              <Area type="monotone" dataKey="amount" stroke="#059669" strokeWidth={2} fill="url(#ga)" />
            </AreaChart>
          </ResponsiveContainer>
        </Card>
        <Card className="p-6">
          <h3 className="text-base font-semibold text-slate-800 mb-4">Distribusi Status</h3>
          <ResponsiveContainer width="100%" height={200}>
            <PieChart><Pie data={pie} dataKey="value" innerRadius={50} outerRadius={80} paddingAngle={2}>{pie.map((e) => <Cell key={e.name} fill={e.color} />)}</Pie><Tooltip /></PieChart>
          </ResponsiveContainer>
          <div className="space-y-1 mt-2">{pie.map((p) => <div key={p.name} className="flex items-center justify-between text-sm"><span className="flex items-center gap-2 text-slate-600"><span className="h-2.5 w-2.5 rounded-full" style={{ background: p.color }} />{p.name}</span><span className="font-semibold tabular-nums">{p.value}</span></div>)}</div>
        </Card>
      </div>
      <Card className="mt-6 p-6">
        <h3 className="text-base font-semibold text-slate-800 mb-4">Transaksi Terbaru</h3>
        <DataTable rows={d.recent} columns={[
          { key: "id", label: "Payment ID", render: (r) => <span className="font-mono text-xs">{r.id}</span> },
          { key: "merchant_id", label: "Merchant", nowrap: true, render: (r) => <span className="font-mono text-xs">{r.merchant_id}</span> },
          { key: "amount", label: "Nominal", align: "right", render: (r) => rupiah(r.amount) },
          { key: "payment_method", label: "Metode" },
          { key: "status", label: "Status", render: (r) => <Badge status={r.status} /> },
          { key: "created_at", label: "Waktu", nowrap: true, render: (r) => fmtDate(r.created_at) },
        ]} />
      </Card>
    </div>
  );
}

/* ------------------------------------------------ Merchants */
export function Merchants() {
  const [status, setStatus] = useState("");
  const { data, loading, refetch } = useFetch(`/merchants?status=${status}`, [status]);
  const { can } = useAuth();
  const act = async (id, action) => { try { await api.post(`/merchants/${id}/${action}`); toast.success("Berhasil"); refetch(); } catch (e) { toast.error(e.response?.data?.detail || "Gagal"); } };
  return (
    <div>
      <PageHeader title="Kelola Merchant" subtitle="Daftar, approval, KYC, dan status akun merchant" />
      <Card>
        <div className="p-4 border-b border-slate-100 flex gap-3">
          <Select value={status} onChange={(e) => setStatus(e.target.value)} className="max-w-[200px]" data-testid="merchant-status-filter">
            <option value="">Semua status</option>{["PENDING", "ACTIVE", "SUSPENDED"].map((s) => <option key={s} value={s}>{s}</option>)}
          </Select>
        </div>
        <DataTable loading={loading} rows={data} columns={[
          { key: "id", label: "Merchant", render: (r) => <Link to={`/admin/merchants/${r.id}`} className="font-medium text-slate-800 hover:text-emerald-600">{r.business_name}<span className="block font-mono text-xs text-slate-400">{r.id}</span></Link> },
          { key: "owner_name", label: "Pemilik" },
          { key: "kyc_status", label: "KYC", render: (r) => <Badge status={r.kyc_status} /> },
          { key: "account_status", label: "Status", render: (r) => <Badge status={r.account_status} /> },
          { key: "pending_balance", label: "Saldo Pending", align: "right", render: (r) => rupiah(r.pending_balance) },
          { key: "actions", label: "Aksi", render: (r) => (
            <div className="flex gap-1">
              <Link to={`/admin/merchants/${r.id}`}><Btn variant="ghost" className="!px-2"><Eye className="h-4 w-4" /></Btn></Link>
              {can("merchant.approve") && r.account_status !== "ACTIVE" && <Btn variant="secondary" className="!px-2 !py-1 text-xs" onClick={() => act(r.id, "approve")} data-testid={`approve-${r.id}`}>Approve</Btn>}
              {can("merchant.suspend") && r.account_status === "ACTIVE" && <Btn variant="danger" className="!px-2 !py-1 text-xs" onClick={() => act(r.id, "suspend")}>Suspend</Btn>}
            </div>
          )},
        ]} />
      </Card>
    </div>
  );
}

export function MerchantDetail() {
  const { id } = useParams();
  const { data, loading, refetch } = useFetch(`/merchants/${id}`);
  const { can } = useAuth();
  if (loading) return <Spinner />;
  if (!data) return <EmptyState title="Merchant tidak ditemukan" />;
  const act = async (action) => { await api.post(`/merchants/${id}/${action}`); toast.success("Berhasil"); refetch(); };
  const kyc = async (s) => { await api.post(`/merchants/${id}/kyc`, { status: s }); toast.success("KYC diperbarui"); refetch(); };
  const rows = [["Merchant ID", data.id], ["Nama Bisnis", data.business_name], ["Pemilik", data.owner_name], ["Email", data.email], ["Telepon", data.phone], ["Alamat", data.address], ["Rekening", data.settlement_account || "-"], ["Fee", `${data.fee_percent}%`], ["Limit", rupiah(data.limit)], ["Dibuat", fmtDate(data.created_at)]];
  return (
    <div>
      <PageHeader title={data.business_name} subtitle={data.id}
        actions={<><Badge status={data.kyc_status} /><Badge status={data.account_status} /></>} />
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2 p-6">
          <h3 className="text-sm font-semibold text-slate-700 mb-4">Informasi Merchant</h3>
          <table className="w-full text-sm"><tbody>{rows.map(([k, v]) => <tr key={k} className="border-b border-slate-50"><td className="py-2.5 text-slate-500 w-40">{k}</td><td className="py-2.5 text-slate-800 font-medium">{v}</td></tr>)}</tbody></table>
        </Card>
        <div className="space-y-6">
          <Card className="p-6">
            <h3 className="text-sm font-semibold text-slate-700 mb-3">Saldo</h3>
            <div className="space-y-3">
              <div className="flex justify-between text-sm"><span className="text-slate-500">Tersedia</span><span className="font-semibold tabular-nums">{rupiah(data.available_balance)}</span></div>
              <div className="flex justify-between text-sm"><span className="text-slate-500">Pending</span><span className="font-semibold tabular-nums">{rupiah(data.pending_balance)}</span></div>
              <div className="flex justify-between text-sm"><span className="text-slate-500">Settled</span><span className="font-semibold tabular-nums">{rupiah(data.settled_balance)}</span></div>
            </div>
          </Card>
          <Card className="p-6 space-y-2">
            <h3 className="text-sm font-semibold text-slate-700 mb-3">Tindakan</h3>
            {can("merchant.approve") && <Btn className="w-full" onClick={() => act("approve")} data-testid="detail-approve">Approve Merchant</Btn>}
            {can("kyc.review") && <Btn variant="secondary" className="w-full" onClick={() => kyc("APPROVED")}>Setujui KYC</Btn>}
            {can("kyc.review") && <Btn variant="secondary" className="w-full" onClick={() => kyc("REJECTED")}>Tolak KYC</Btn>}
            {can("merchant.suspend") && <Btn variant="danger" className="w-full" onClick={() => act("suspend")}>Suspend</Btn>}
          </Card>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------ generic list */
function ListPage({ title, subtitle, endpoint, columns, filters, toolbar }) {
  const [status, setStatus] = useState("");
  const [q, setQ] = useState("");
  const url = `${endpoint}${endpoint.includes("?") ? "&" : "?"}status=${status}&search=${q}`;
  const { data, loading } = useFetch(url, [status, q]);
  return (
    <div>
      <PageHeader title={title} subtitle={subtitle} actions={toolbar} />
      <Card>
        {(filters || filters === undefined) && (
          <div className="p-4 border-b border-slate-100 flex flex-wrap gap-3">
            <Input placeholder="Cari..." value={q} onChange={(e) => setQ(e.target.value)} className="max-w-xs" data-testid="list-search" />
            {filters && <Select value={status} onChange={(e) => setStatus(e.target.value)} className="max-w-[180px]"><option value="">Semua status</option>{filters.map((s) => <option key={s} value={s}>{s}</option>)}</Select>}
          </div>
        )}
        <DataTable loading={loading} rows={data} columns={columns} />
      </Card>
    </div>
  );
}

