export function Fees() {
  const { data, loading, refetch } = useFetch("/fees");
  const { can } = useAuth();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: "", method: "QRIS", percent: 0.7, fixed: 0, min_fee: 0, max_fee: 0 });
  const save = async () => { try { await api.post("/fees", { ...form, percent: parseFloat(form.percent), fixed: parseInt(form.fixed), min_fee: parseInt(form.min_fee), max_fee: parseInt(form.max_fee) }); toast.success("Fee disimpan"); setOpen(false); refetch(); } catch { toast.error("Gagal"); } };
  const del = async (id) => { await api.delete(`/fees/${id}`); toast.success("Dihapus"); refetch(); };
  return (
    <div>
      <PageHeader title="Manajemen Fee" subtitle="Atur biaya per metode pembayaran"
        actions={can("fee.update") && <Btn onClick={() => setOpen(true)} data-testid="fee-new"><Plus className="h-4 w-4" /> Tambah Fee</Btn>} />
      <Card><DataTable loading={loading} rows={data} columns={[
        { key: "name", label: "Nama" }, { key: "method", label: "Metode", render: (r) => <Badge>{r.method}</Badge> },
        { key: "percent", label: "Persentase", render: (r) => `${r.percent}%` },
        { key: "fixed", label: "Fixed", render: (r) => rupiah(r.fixed) },
        { key: "min_fee", label: "Min", render: (r) => rupiah(r.min_fee) },
        { key: "max_fee", label: "Maks", render: (r) => r.max_fee ? rupiah(r.max_fee) : "-" },
        { key: "actions", label: "", render: (r) => can("fee.update") && <Btn variant="danger" className="!px-2" onClick={() => del(r.id)}><Trash2 className="h-4 w-4" /></Btn> },
      ]} /></Card>
      <Modal open={open} onClose={() => setOpen(false)} title="Tambah Fee" footer={<><Btn variant="secondary" onClick={() => setOpen(false)}>Batal</Btn><Btn onClick={save}>Simpan</Btn></>}>
        <div className="space-y-4">
          <Field label="Nama"><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} data-testid="fee-name" /></Field>
          <Field label="Metode"><Select value={form.method} onChange={(e) => setForm({ ...form, method: e.target.value })}>{["QRIS", "VA", "E-WALLET", "BANK_TRANSFER", "CARD"].map((m) => <option key={m}>{m}</option>)}</Select></Field>
          <div className="grid grid-cols-2 gap-4">
            <Field label="Persentase (%)"><Input type="number" step="0.1" value={form.percent} onChange={(e) => setForm({ ...form, percent: e.target.value })} /></Field>
            <Field label="Fixed (Rp)"><Input type="number" value={form.fixed} onChange={(e) => setForm({ ...form, fixed: e.target.value })} /></Field>
            <Field label="Min Fee"><Input type="number" value={form.min_fee} onChange={(e) => setForm({ ...form, min_fee: e.target.value })} /></Field>
            <Field label="Maks Fee"><Input type="number" value={form.max_fee} onChange={(e) => setForm({ ...form, max_fee: e.target.value })} /></Field>
          </div>
        </div>
      </Modal>
    </div>
  );
}

