export function AdminWithdrawals() {
  const [status, setStatus] = useState("PENDING");
  const { data, loading, refetch } = useFetch(`/withdrawals?status=${status}`, [status]);
  const { can } = useAuth();
  const review = async (id, approve) => {
    let reason = "";
    if (!approve) { reason = window.prompt("Alasan penolakan penarikan?") || ""; }
    try { await api.post(`/withdrawals/${id}/approve`, { approve, reason }); toast.success(approve ? "Penarikan disetujui & diproses" : "Penarikan ditolak"); refetch(); }
    catch (e) { toast.error(e.response?.data?.detail || "Gagal"); }
  };
  return (
    <div>
      <PageHeader title="Persetujuan Penarikan" subtitle="Tinjau & setujui permintaan penarikan dana merchant" />
      <div className="flex gap-2 mb-4">
        {["PENDING", "COMPLETED", "REJECTED", ""].map((s) => (
          <Btn key={s || "all"} variant={status === s ? "primary" : "secondary"} onClick={() => setStatus(s)} className="!py-1.5">{s === "" ? "Semua" : s === "PENDING" ? "Menunggu" : s === "COMPLETED" ? "Selesai" : "Ditolak"}</Btn>
        ))}
      </div>
      <Card><DataTable loading={loading} rows={data} columns={[
        { key: "id", label: "ID", render: (r) => <span className="font-mono text-xs">{r.id}</span> },
        { key: "merchant_name", label: "Merchant", render: (r) => <span>{r.merchant_name}<span className="block font-mono text-[10px] text-slate-400">{r.merchant_id}</span></span> },
        { key: "amount", label: "Nominal", align: "right", render: (r) => rupiah(r.amount) },
        { key: "fee", label: "Biaya", align: "right", render: (r) => rupiah(r.fee || 0) },
        { key: "net_amount", label: "Diterima", align: "right", render: (r) => rupiah(r.net_amount ?? r.amount) },
        { key: "bank_account", label: "Rekening Tujuan", render: (r) => r.bank_account || "-" },
        { key: "note", label: "Catatan", render: (r) => r.note || "-" },
        { key: "status", label: "Status", render: (r) => <Badge status={r.status} /> },
        { key: "created_at", label: "Diajukan", nowrap: true, render: (r) => fmtDate(r.created_at) },
        { key: "actions", label: "Aksi", render: (r) => can("withdrawal.approve") && r.status === "PENDING" ? (
          <div className="flex gap-1">
            <Btn variant="secondary" className="!px-2 !py-1 text-xs" onClick={() => review(r.id, true)} data-testid={`wd-approve-${r.id}`}>Setujui</Btn>
            <Btn variant="danger" className="!px-2 !py-1 text-xs" onClick={() => review(r.id, false)}>Tolak</Btn>
          </div>
        ) : (r.reviewed_by ? <span className="text-xs text-slate-400">oleh {r.reviewed_by}{r.reject_reason ? ` · ${r.reject_reason}` : ""}</span> : "-") },
      ]} empty={<EmptyState title="Tidak ada penarikan" />} /></Card>
    </div>
  );
}
