/* ------------------------------------------------ Create Payment (QRIS) */
export function CreatePayment() {
  const [form, setForm] = useState({ amount: "", merchant_reference: "", description: "", customer_name: "" });
  const [payment, setPayment] = useState(null);
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("PENDING");
  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  const create = async (e) => {
    e.preventDefault();
    setBusy(true);
    try {
      const { data } = await api.post("/payments", { ...form, amount: parseInt(form.amount, 10) });
      setPayment(data); setStatus(data.status);
      toast.success("QRIS berhasil dibuat");
      poll(data.id);
    } catch (err) { toast.error(err.response?.data?.detail || "Gagal membuat QRIS"); }
    setBusy(false);
  };

  const poll = (id) => {
    const iv = setInterval(async () => {
      try {
        const { data } = await api.get(`/payments/${id}/status`);
        setStatus(data.status);
        if (["PAID", "EXPIRED", "CANCELLED"].includes(data.status)) { clearInterval(iv); if (data.status === "PAID") toast.success("Pembayaran diterima!"); }
      } catch { clearInterval(iv); }
    }, 3500);
    setTimeout(() => clearInterval(iv), 120000);
  };

  const simulate = async () => {
    try { await api.post(`/payments/${payment.id}/simulate-paid`); setStatus("PAID"); toast.success("Pembayaran disimulasikan berhasil"); }
    catch { toast.error("Gagal simulasi"); }
  };

  const reset = () => { setPayment(null); setStatus("PENDING"); setForm({ amount: "", merchant_reference: "", description: "", customer_name: "" }); };

  return (
    <div>
      <PageHeader title="Buat Pembayaran QRIS" subtitle="Buat QRIS dinamis dengan nominal tertentu" />
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 max-w-4xl">
        <Card className="p-6">
          <form onSubmit={create} className="space-y-4">
            <Field label="Nominal (IDR)"><Input type="number" min="1" required value={form.amount} onChange={set("amount")} placeholder="15000" data-testid="pay-amount" disabled={!!payment} /></Field>
            <Field label="Referensi Order" hint="Kosongkan untuk otomatis"><Input value={form.merchant_reference} onChange={set("merchant_reference")} placeholder="ORDER-10001" data-testid="pay-ref" disabled={!!payment} /></Field>
            <Field label="Nama Pelanggan"><Input value={form.customer_name} onChange={set("customer_name")} placeholder="Opsional" disabled={!!payment} /></Field>
            <Field label="Deskripsi"><Input value={form.description} onChange={set("description")} placeholder="Opsional" disabled={!!payment} /></Field>
            {!payment ? (
              <Btn type="submit" disabled={busy} className="w-full" data-testid="pay-submit">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <>Buat QRIS <ArrowRight className="h-4 w-4" /></>}</Btn>
            ) : (
              <Btn type="button" variant="secondary" onClick={reset} className="w-full" data-testid="pay-new"><Plus className="h-4 w-4" /> Buat Pembayaran Baru</Btn>
            )}
          </form>
        </Card>
        <Card className="p-8 flex flex-col items-center justify-center">
          {!payment ? (
            <div className="text-center text-slate-400">
              <QrCode className="h-16 w-16 mx-auto mb-4 text-slate-200" />
              <p className="text-sm">QR akan muncul di sini setelah dibuat</p>
            </div>
          ) : (
            <div className="text-center w-full" data-testid="qris-panel">
              <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full border mb-6 text-sm font-semibold"
                style={{}} data-testid="qris-status">
                <span className={`h-2.5 w-2.5 rounded-full ${status === "PAID" ? "bg-emerald-500" : status === "PENDING" ? "bg-amber-500 animate-pulse" : "bg-red-500"}`} />
                {status === "PAID" ? "Pembayaran Berhasil" : status === "PENDING" ? "Menunggu Pembayaran" : status}
              </div>
              <div className="p-6 bg-white border border-slate-200 rounded-2xl inline-block shadow-sm">
                {status === "PAID" ? (
                  <div className="h-[220px] w-[220px] flex items-center justify-center"><CheckCircle2 className="h-24 w-24 text-emerald-500" /></div>
                ) : payment.qr_image && payment.qr_source === "gomerch" ? (
                  <img src={payment.qr_image} alt="QRIS" className="h-[220px] w-[220px] object-contain" />
                ) : (
                  <QRCodeCanvas value={`GOMERCH|${payment.id}|${payment.amount}`} size={220} level="M" fgColor="#0f172a" />
                )}
              </div>
              <p className="text-3xl font-bold font-heading text-slate-900 mt-6 tabular-nums">{rupiah(payment.amount)}</p>
              <p className="text-xs text-slate-400 mt-1 font-mono">{payment.id} · Fee {rupiah(payment.fee)}</p>
              {payment.qr_source !== "gomerch" && status === "PENDING" && (
                <p className="text-xs text-amber-600 mt-3 bg-amber-50 rounded-md px-3 py-2">QRIS statis merchant belum diatur di GoMerch — menampilkan QR contoh. Atur di Akun › Integrasi.</p>
              )}
              {status === "PENDING" && (
                <Btn variant="secondary" onClick={simulate} className="mt-4" data-testid="qris-simulate"><TestTube2 className="h-4 w-4" /> Simulasikan Pembayaran</Btn>
              )}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

