export function Webhooks() {
  const { data, loading, refetch } = useFetch("/webhooks");
  const { data: deliveries } = useFetch("/webhook-deliveries");
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const create = async () => { try { await api.post("/webhooks", { url, events: ["payment.paid", "payment.failed", "refund.completed"] }); toast.success("Endpoint ditambahkan"); setOpen(false); setUrl(""); refetch(); } catch { toast.error("Gagal"); } };
  const test = async (id) => { await api.post(`/webhooks/${id}/test`); toast.success("Test webhook dikirim"); };
  const del = async (id) => { await api.delete(`/webhooks/${id}`); toast.success("Dihapus"); refetch(); };
  return (
    <div>
      <PageHeader title="Webhook" subtitle="Terima notifikasi event pembayaran secara real-time"
        actions={<Btn onClick={() => setOpen(true)} data-testid="hook-new"><Plus className="h-4 w-4" /> Tambah Endpoint</Btn>} />
      <div className="space-y-4 mb-6">
        {loading ? <Spinner /> : (!data || data.length === 0) ? <Card className="p-6"><EmptyState title="Belum ada endpoint" /></Card> :
          data.map((h) => (
            <Card key={h.id} className="p-5 flex flex-wrap items-center justify-between gap-3">
              <div className="min-w-0"><div className="flex items-center gap-2"><Webhook className="h-4 w-4 text-emerald-600" /><code className="text-sm text-slate-800 truncate">{h.url}</code></div>
                <div className="flex flex-wrap gap-1 mt-2">{h.events.map((e) => <Badge key={e}>{e}</Badge>)}</div></div>
              <div className="flex gap-2"><Btn variant="secondary" onClick={() => test(h.id)}><TestTube2 className="h-4 w-4" /> Test</Btn><Btn variant="danger" onClick={() => del(h.id)}><Trash2 className="h-4 w-4" /></Btn></div>
            </Card>
          ))}
      </div>
      <Card>
        <div className="px-4 py-3 border-b border-slate-100"><h3 className="text-sm font-semibold text-slate-700">Log Pengiriman</h3></div>
        <DataTable rows={deliveries} columns={[
          { key: "event", label: "Event", render: (r) => <Badge>{r.event}</Badge> },
          { key: "url", label: "URL", render: (r) => <code className="text-xs">{r.url}</code> },
          { key: "http_status", label: "HTTP", render: (r) => <span className="font-mono text-xs">{r.http_status}</span> },
          { key: "latency_ms", label: "Latensi", render: (r) => `${r.latency_ms}ms` },
          { key: "status", label: "Status", render: (r) => <Badge status={r.status} /> },
          { key: "timestamp", label: "Waktu", nowrap: true, render: (r) => fmtDate(r.timestamp) },
        ]} empty={<EmptyState title="Belum ada log pengiriman" />} />
      </Card>
      <Modal open={open} onClose={() => setOpen(false)} title="Tambah Webhook Endpoint"
        footer={<><Btn variant="secondary" onClick={() => setOpen(false)}>Batal</Btn><Btn onClick={create} data-testid="hook-submit">Simpan</Btn></>}>
        <Field label="URL Endpoint"><Input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://toko.com/webhook" data-testid="hook-url" /></Field>
      </Modal>
    </div>
  );
}

